export const clamp=(x,a=0,b=1)=>Math.max(a,Math.min(b,x));
export const FACE_FILTERS=['Original','Giant Head','Tiny Head','Huge Mouth','Giant Eyes','Tiny Eyes','Giant Nose','Long Chin','Big Forehead','Squished Face','Wide Face','Long Face','Fish-Eye Face','Jelly Face','Giant Smile','Alien Head','Exaggerated Cheeks','Funny Mirror','Random Face'];
export const LIVE_EFFECTS=['None','Fire Breath','Rainbow Mouth','Laser Eyes','Bouncing Animal Ears','Robot Face','Dragon Transformation','Alien Transformation','Cartoon Dog','Cartoon Cat','Pirate','Wizard','Superhero','Astronaut','Monster','Clown','Bubble Head'];
export const VOICE_EFFECTS=['Original','Chipmunk','Deep Voice','Robot','Alien','Echo','Monster','Cartoon Squeaky Voice','Slow Voice','Fast Voice','Reverb'];
export function faceGeometry(points,w=1280,h=720){if(!points?.[454])return null;const at=i=>({x:points[i].x*w,y:points[i].y*h}),a=at(33),b=at(263),left=at(234),right=at(454),top=at(10),chin=at(152),mouth=at(13),nose=at(1);return{center:{x:(left.x+right.x)/2,y:(top.y+chin.y)/2},rx:Math.max(12,Math.hypot(left.x-right.x,left.y-right.y)*.58),ry:Math.max(18,Math.hypot(top.x-chin.x,top.y-chin.y)*.59),angle:Math.atan2(b.y-a.y,b.x-a.x),eyes:[a,b],mouth,nose,chin,top,mouthWidth:Math.max(10,Math.hypot(at(61).x-at(291).x,at(61).y-at(291).y))};}
export function deformPoint(x,y,face,filter,intensity=1,time=0){if(!face||filter==='Original'||intensity<=0)return{x,y};const k=clamp(intensity,0,1.6)*(face.fade??1),c=Math.cos(face.angle),s=Math.sin(face.angle),dx=x-face.center.x,dy=y-face.center.y,u=c*dx+s*dy,v=-s*dx+c*dy;let du=0,dv=0;const local=p=>({x:c*(p.x-face.center.x)+s*(p.y-face.center.y),y:-s*(p.x-face.center.x)+c*(p.y-face.center.y)}),gauss=(a,b,rx,ry)=>Math.exp(-(((u-a)/rx)**2*2+((v-b)/ry)**2*2)),bulge=(p,rx,ry,sx,sy=sx)=>{const q=local(p),g=gauss(q.x,q.y,rx,ry);du+=(u-q.x)*sx*g*k;dv+=(v-q.y)*sy*g*k;},mouth=local(face.mouth),head=gauss(0,0,face.rx*1.6,face.ry*1.4);
 if(filter==='Random Face')filter=FACE_FILTERS[1+(Math.floor(time/1000000000)||7)%17];
 if(filter==='Giant Head')bulge(face.center,face.rx*1.7,face.ry*1.5,.8);
 if(filter==='Tiny Head')bulge(face.center,face.rx*1.8,face.ry*1.6,-.65);
 if(filter==='Huge Mouth')bulge(face.mouth,face.rx*.8,face.ry*.45,2.2,2.6);
 if(filter==='Giant Eyes'||filter==='Tiny Eyes')for(const p of face.eyes)bulge(p,face.rx*.43,face.ry*.29,filter==='Giant Eyes'?2.4:-.78);
 if(filter==='Giant Nose')bulge(face.nose,face.rx*.4,face.ry*.5,2.5,1.6);
 if(filter==='Long Chin'){const q=local(face.chin);dv+=face.ry*.7*gauss(q.x,q.y,face.rx*.9,face.ry*.55)*k;}
 if(filter==='Big Forehead'){const q=local(face.top);dv-=face.ry*.55*gauss(q.x,q.y,face.rx,face.ry*.6)*k;du+=u*.25*head*k;}
 if(filter==='Squished Face'){du+=u*.38*head*k;dv-=v*.5*head*k;}
 if(filter==='Wide Face')du+=u*.95*head*k;
 if(filter==='Long Face')dv+=v*.9*head*k;
 if(filter==='Fish-Eye Face')bulge(face.nose,face.rx*1.3,face.ry*1.15,1.4);
 if(filter==='Jelly Face'){du+=Math.sin(v/face.ry*4+time/240)*face.rx*.27*head*k;dv+=Math.sin(u/face.rx*4+time/330)*face.ry*.12*head*k;}
 if(filter==='Giant Smile'){const g=gauss(mouth.x,mouth.y,face.rx*.9,face.ry*.35);du+=(u-mouth.x)*1.5*g*k;dv-=Math.abs(u-mouth.x)*.42*g*k;}
 if(filter==='Alien Head'){bulge(face.top,face.rx*1.15,face.ry*.8,.8,1.1);for(const p of face.eyes)bulge(p,face.rx*.4,face.ry*.3,1.5,1.2);du-=u*.2*gauss(0,face.ry*.5,face.rx,face.ry)*k;}
 if(filter==='Exaggerated Cheeks')for(const sign of [-1,1]){const p={x:face.center.x+sign*face.rx*.55*c-face.ry*.13*s,y:face.center.y+sign*face.rx*.55*s+face.ry*.13*c};bulge(p,face.rx*.6,face.ry*.5,1.7);}
 if(filter==='Funny Mirror'){du+=Math.sin(v/face.ry*3)*face.rx*.5*head*k;dv+=u*.18*head*k;}
 return{x:x+c*du-s*dv,y:y+s*du+c*dv};}
export function buildMesh(faces,filters,intensity,time,w,h,cols=40,rows=24){const vertices=[],uv=[],indices=[];for(let j=0;j<=rows;j++)for(let i=0;i<=cols;i++){const x=i/cols*w,y=j/rows*h;let px=x,py=y;for(const face of faces)for(const filter of filters){const q=deformPoint(x,y,face,filter,intensity,time);px+=q.x-x;py+=q.y-y;}vertices.push(px/w*2-1,1-py/h*2);uv.push(i/cols,j/rows);}for(let j=0;j<rows;j++)for(let i=0;i<cols;i++){const a=j*(cols+1)+i,b=a+1,c=a+cols+1;indices.push(a,c,b,b,c,c+1);}return{vertices:new Float32Array(vertices),uv:new Float32Array(uv),indices:new Uint16Array(indices)};}
export function expressions(blend=[],points=[],level=0){const b=Object.fromEntries(blend.map(x=>[x.categoryName,x.score])),get=k=>clamp(b[k]||0);return{mouth:Math.max(get('jawOpen'),clamp(level*4)),smile:(get('mouthSmileLeft')+get('mouthSmileRight'))/2,blink:(get('eyeBlinkLeft')+get('eyeBlinkRight'))/2,brows:Math.max(get('browInnerUp'),(get('browOuterUpLeft')+get('browOuterUpRight'))/2),frown:(get('mouthFrownLeft')+get('mouthFrownRight'))/2,tilt:points[33]&&points[263]?Math.atan2(points[263].y-points[33].y,points[263].x-points[33].x):0};}
export class ExpressionState{constructor(){this.value={mouth:0,smile:0,blink:0,brows:0,frown:0,tilt:0};this.baseline={};this.sensitivity=1;}calibrate(){this.baseline={...this.value};}update(next,dt=80){const a=1-Math.exp(-Math.min(200,dt)/110);for(const k of Object.keys(this.value)){const target=k==='tilt'?(next[k]||0):clamp(((next[k]||0)-(this.baseline[k]||0)*.8)*this.sensitivity);this.value[k]+=(target-this.value[k])*a;}return this.value;}}
export class EditHistory{constructor(state){this.state=structuredClone(state);this.past=[];this.future=[];}change(fn){this.past.push(structuredClone(this.state));if(this.past.length>35)this.past.shift();this.future=[];fn(this.state);}undo(){if(!this.past.length)return;this.future.push(this.state);this.state=this.past.pop();}redo(){if(!this.future.length)return;this.past.push(this.state);this.state=this.future.pop();}}
export const freshEdit=()=>({filters:['Original'],intensity:1,effect:'None',mirror:true,brightness:1,contrast:1,saturation:1,rotation:0,flip:false,crop:{x:0,y:0,w:1,h:1},frame:'None',layers:[],drawing:[],text:'',volume:1,speed:1});
export const POSES=['smile','mouth','blink','brows','tilt','frown'];
export class PoseChallenge{constructor({mode='expression',difficulty=3,seed=1}={}){this.mode=mode;this.difficulty=difficulty;let n=seed>>>0;const rnd=()=>((n=Math.imul(n,1664525)+1013904223>>>0)/4294967296);this.plan=Array.from({length:mode==='mimic'?3+difficulty:5},()=>POSES[Math.floor(rnd()*POSES.length)]);this.clock=0;this.index=0;this.held=0;this.score=0;this.hits=0;this.errors=0;this.done=false;this.max=45000+this.plan.length*2000;this.stage=mode==='mimic'?'watch':'copy';this.watchUntil=this.plan.length*1100;}get target(){return this.stage==='watch'?this.plan[Math.min(this.plan.length-1,Math.floor(this.clock/1100))]:this.plan[this.index];}step(dt,e,valid=true){if(this.done)return;this.clock+=dt;if(this.stage==='watch'){if(this.clock>=this.watchUntil)this.stage='copy';return;}const value=this.target==='tilt'?Math.abs(e.tilt||0)*1.5:e[this.target]||0,threshold=[.25,.32,.4,.46,.52][this.difficulty-1];if(valid&&value>threshold)this.held+=dt;else this.held=Math.max(0,this.held-dt*.6);if(this.held>450+this.difficulty*70){this.hits++;this.score+=Math.round(200+Math.max(0,150-this.clock/600));this.index++;this.held=0;if(this.index>=this.plan.length)this.done=true;}if(this.clock>=this.max)this.done=true;}summary(){return{score:this.score,hits:this.hits,errors:this.errors,completed:this.index===this.plan.length,duration:this.clock/1000};}}
export function audioPitch(samples,sampleRate){let energy=0;for(const x of samples)energy+=x*x;const rms=Math.sqrt(energy/samples.length);if(rms<.008)return{rms,pitch:0};let best=0,lag=0;const correlations=[];for(let n=Math.floor(sampleRate/650);n<Math.min(samples.length/2,sampleRate/65);n++){let s=0,a=0,b=0;for(let i=0;i<samples.length-n;i+=2){s+=samples[i]*samples[i+n];a+=samples[i]**2;b+=samples[i+n]**2;}const value=s/Math.sqrt(a*b||1);correlations.push({n,value});if(value>best){best=value;lag=n;}}for(let i=1;i<correlations.length-1;i++){const c=correlations[i];if(c.value>Math.max(.8,best*.96)&&c.value>=correlations[i-1].value&&c.value>=correlations[i+1].value){lag=c.n;break;}}return{rms,pitch:best>.75?sampleRate/lag:0};}
